using System;
using System.Collections;
using System.Linq;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using TMPro;
using Object=UnityEngine.Object;
namespace Dhara.Tests {
public sealed class ExplorationRuntimeTests {
DharaApplication app; OrbitCamera o; EnvironmentalDashboard ui;
WeatherData W(double rain=40,double wind=40)=>new WeatherData{Time="2026-01-01T12:00",RainMmPerHour=rain,Temperature=25,WindKmh=wind,WindDegrees=90,CloudPercent=30,SolarWm2=600};
void IsolateStartup(Scene scene,LoadSceneMode mode){foreach(var root in scene.GetRootGameObjects())foreach(var a in root.GetComponentsInChildren<DharaApplication>(true))a.FetchDataOnStart=false;}
[Serializable] class PlayerProbe{public bool responding=false;public bool hasWindow=false;}
[UnitySetUp] public IEnumerator Setup(){SceneManager.sceneLoaded+=IsolateStartup;yield return SceneManager.LoadSceneAsync("Dhara");yield return null;app=Object.FindFirstObjectByType<DharaApplication>();app.enabled=false;app.Weather.CancelRequests();app.AirQuality.Cancel();app.History.Cancel();app.Weather.RequestUrl=_=>"http://127.0.0.1:9/failure";app.AirQuality.RequestUrl=_=>"http://127.0.0.1:9/failure";o=app.World.ViewCamera.GetComponent<OrbitCamera>();o.enabled=false;ui=app.GetComponent<EnvironmentalDashboard>();}
[UnityTearDown] public IEnumerator Cleanup(){SceneManager.sceneLoaded-=IsolateStartup;if(app!=null)Object.Destroy(app.gameObject);yield return null;}
ParticleSystem P(string n)=>app.World.transform.Find(n).GetComponent<ParticleSystem>();
void Draw(double rain=40,double wind=40,double volume=30,double wet=1,double cloud=30,double solar=600,string time="2026-01-01T12:00"){
 var w=W(rain,wind);w.CloudPercent=cloud;w.SolarWm2=solar;w.Time=time;
 app.World.Render(new EnvironmentState{RainIntensity=rain/200,WindIntensity=wind/180,CollectionM3=volume,Wetness=wet,LightIntensity=1.35-cloud*.009},w,5);
}
void RefreshUi(){typeof(EnvironmentalDashboard).GetField("nextRefresh",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(ui,0f);ui.SendMessage("Update");Canvas.ForceUpdateCanvases();}
Transform Root=>app.transform.Find("Environmental monitoring dashboard");
void Click(string path)=>Root.Find(path).GetComponent<UnityEngine.UI.Button>().onClick.Invoke();
void StepMove(Vector2 v,int n=20){for(int i=0;i<n;i++)o.MoveExplorer(v,.05f);}
string ReadShared(string path){using(var stream=new System.IO.FileStream(path,System.IO.FileMode.Open,System.IO.FileAccess.Read,System.IO.FileShare.ReadWrite))using(var reader=new System.IO.StreamReader(stream))return reader.ReadToEnd();}
IEnumerator RequestDone(){float end=Time.realtimeSinceStartup+26;while(app.Weather.Status.Loading&&Time.realtimeSinceStartup<end)yield return null;Assert.That(app.Weather.Status.Loading,Is.False);}
[UnityTest] public IEnumerator B11_Http400IsRejected(){using(var fault=new ApplicationTests.FaultEndpoint(400,"{}")){app.Weather.RequestUrl=_=>fault.Url;app.Weather.Select(0);yield return RequestDone();Assert.That(app.Weather.Status.Error,Is.Not.Null);Assert.That(app.Weather.Current,Is.Null);}}
[UnityTest] public IEnumerator B12_Http429IsRejected(){using(var fault=new ApplicationTests.FaultEndpoint(429,"{}")){app.Weather.RequestUrl=_=>fault.Url;app.Weather.Select(0);yield return RequestDone();Assert.That(app.Weather.Status.Error,Is.Not.Null);Assert.That(app.Weather.Current,Is.Null);}}
[UnityTest] public IEnumerator B13_Http500IsRejected(){using(var fault=new ApplicationTests.FaultEndpoint(500,"{}")){app.Weather.RequestUrl=_=>fault.Url;app.Weather.Select(0);yield return RequestDone();Assert.That(app.Weather.Status.Error,Is.Not.Null);Assert.That(app.Weather.Current,Is.Null);}}
[UnityTest] public IEnumerator B14_RealRequestTimeoutRetainsNoSuccess(){using(var f=new ApplicationTests.FaultEndpoint(200,"",true)){app.Weather.RequestUrl=_=>f.Url;float start=Time.realtimeSinceStartup;app.Weather.Select(0);yield return RequestDone();Assert.That(Time.realtimeSinceStartup-start,Is.InRange(19,26));Assert.That(app.Weather.Status.Error,Is.Not.Null);}}
[Test] public void B15_CancelStopsPendingRequest(){using(var f=new ApplicationTests.FaultEndpoint(200,"",true)){app.Weather.RequestUrl=_=>f.Url;app.Weather.Select(0);app.Weather.CancelRequests();Assert.That(app.Weather.Status.Loading,Is.False);Assert.That(app.Weather.Current,Is.Null);}}
[UnityTest] public IEnumerator B16_DisconnectionDoesNotInventWeather(){app.Weather.RequestUrl=_=>"https://dhara-offline.invalid/";app.Weather.Select(0);yield return RequestDone();Assert.That(app.Weather.Status.Error,Is.Not.Null);Assert.That(app.Weather.Current,Is.Null);}
[UnityTest] public IEnumerator B17_NewCityRejectsObsoleteRequest(){using(var f=new ApplicationTests.FaultEndpoint(500,"{}",true)){app.Weather.RequestUrl=_=>f.Url;app.Weather.Select(0);app.Weather.RequestUrl=WeatherRequest.Url;app.Weather.Select(1);yield return RequestDone();Assert.That(app.Weather.Selected,Is.EqualTo(1));Assert.That(app.Weather.Current,Is.Not.Null,app.Weather.Status.Error);}}
[Test] public void C01_OverviewCameraValid(){o.Home();o.AdvanceCamera(.1f);Assert.That(app.World.ViewCamera.transform.position.y,Is.GreaterThan(20));}
[Test] public void C02_OverviewFacesTheDistrict(){o.Home();o.AdvanceCamera(.1f);Assert.That(Vector3.Dot(o.transform.forward,-o.transform.position.normalized),Is.GreaterThan(.8f));}
[Test] public void C03_ZoomNearBound(){o.Home();o.Zoom(100000);Assert.That(o.OverviewDistance,Is.EqualTo(12));}
[Test] public void C04_ZoomFarBound(){o.Home();o.Zoom(-100000);Assert.That(o.OverviewDistance,Is.EqualTo(300));}
[Test] public void C05_ForwardMovement(){o.EnterExplorer(Vector3.zero);StepMove(Vector2.up);Assert.That(o.transform.position.z,Is.GreaterThan(0));}
[Test] public void C06_BackwardMovement(){o.EnterExplorer(Vector3.zero);StepMove(Vector2.down);Assert.That(o.transform.position.z,Is.LessThan(0));}
[Test] public void C07_LeftMovement(){o.EnterExplorer(Vector3.zero);StepMove(Vector2.left);Assert.That(o.transform.position.x,Is.LessThan(0));}
[Test] public void C08_RightMovement(){o.EnterExplorer(Vector3.zero);StepMove(Vector2.right);Assert.That(o.transform.position.x,Is.GreaterThan(0));}
[Test] public void C09_FullHorizontalTurn(){o.EnterExplorer(Vector3.zero);o.LookExplorer(new Vector2(1500,0));Assert.That(o.HorizontalAngle,Is.EqualTo(300).Within(.001f));o.LookExplorer(new Vector2(300,0));Assert.That(o.HorizontalAngle,Is.EqualTo(0).Within(.001f));}
[Test] public void C10_PitchDoesNotFlip(){o.EnterExplorer(Vector3.zero);o.LookExplorer(new Vector2(0,10000));Assert.That(o.VerticalAngle,Is.EqualTo(-65));o.LookExplorer(new Vector2(0,-20000));Assert.That(o.VerticalAngle,Is.EqualTo(65));}
[Test] public void C11_ForwardFollowsHeading(){o.EnterExplorer(Vector3.zero);o.LookExplorer(new Vector2(450,0));StepMove(Vector2.up);Assert.That(o.transform.position.x,Is.GreaterThan(3));Assert.That(Mathf.Abs(o.transform.position.z),Is.LessThan(.01f));}
[Test] public void C12_SubdividedMovementConsistent(){o.EnterExplorer(Vector3.zero);for(int i=0;i<20;i++)o.MoveExplorer(Vector2.up,.1f);float a=o.transform.position.z;o.EnterExplorer(Vector3.zero);for(int i=0;i<40;i++)o.MoveExplorer(Vector2.up,.05f);Assert.That(o.transform.position.z,Is.EqualTo(a).Within(.05f));}
[Test] public void C13_GroundPlaneIsMaintained(){o.EnterExplorer(new Vector3(0,-999,0));StepMove(Vector2.up);Assert.That(o.transform.position.y,Is.EqualTo(2.2f));}
[Test] public void C14_BuildingFootprintsBlockMovement(){o.EnterExplorer(new Vector3(0,2.2f,23));StepMove(Vector2.right,300);Assert.That(o.transform.position.x,Is.LessThan(12));}
[Test] public void C15_InvalidSpawnRecovers(){o.EnterExplorer(new Vector3(float.NaN,0,0));Assert.That(o.transform.position,Is.EqualTo(new Vector3(0,2.2f,-34)));}
[Test] public void C16_OverviewEntersStreet(){o.Home();o.ToStreet();o.AdvanceCamera(5);Assert.That(o.IsExploring,Is.True);Assert.That(o.transform.position.y,Is.EqualTo(2.2f).Within(.01f));}
[Test] public void C17_StreetReturnsToOverview(){o.EnterExplorer(Vector3.zero);o.ToOverview();o.AdvanceCamera(2);Assert.That(o.IsExploring||o.IsTransitioning,Is.False);Assert.That(o.transform.position.y,Is.GreaterThan(20));}
[Test] public void C18_UiBlocksLook(){o.EnterExplorer(Vector3.zero);o.LookExplorer(new Vector2(100,100),true);Assert.That(o.HorizontalAngle,Is.Zero);Assert.That(o.VerticalAngle,Is.Zero);}
[Test] public void C19_ReleasedFocusBlocksMovement(){o.EnterExplorer(Vector3.zero);o.ReleaseInput();StepMove(Vector2.up);Assert.That(o.transform.position.z,Is.Zero);o.CaptureInput();StepMove(Vector2.up);Assert.That(o.transform.position.z,Is.GreaterThan(0));}
[Test] public void C20_ResetRecoversCamera(){o.EnterExplorer(Vector3.zero);o.LookExplorer(new Vector2(500,80));o.Home();o.AdvanceCamera(.1f);Assert.That(o.IsExploring,Is.False);Assert.That(o.transform.position.y,Is.GreaterThan(20));}
[Test] public void D01_TourStarts(){o.StartTour();Assert.That(o.TourRunning,Is.True);}
[Test] public void D02_TourPauseFreezesPosition(){o.StartTour();o.AdvanceCamera(3);o.PauseTour();var p=o.transform.position;o.AdvanceCamera(20);Assert.That(o.transform.position,Is.EqualTo(p));Assert.That(o.TourPaused,Is.True);}
[Test] public void D03_TourResumeMoves(){o.StartTour();o.PauseTour();o.ResumeTour();var p=o.transform.position;o.AdvanceCamera(2);Assert.That(Vector3.Distance(p,o.transform.position),Is.GreaterThan(1));}
[Test] public void D04_TourRestartReturnsToStart(){o.StartTour();var p=o.transform.position;o.AdvanceCamera(25);o.RestartTour();Assert.That(o.transform.position,Is.EqualTo(p));}
[Test] public void D05_TourExitRestoresOverview(){o.StartTour();o.AdvanceCamera(20);o.CancelTour();Assert.That(o.TourRunning||o.IsTransitioning,Is.False);Assert.That(o.transform.position.y,Is.GreaterThan(20));}
[Test] public void D06_RouteHasDistinctPositions(){o.StartTour();Assert.That(o.TourWaypoints.Distinct().Count(),Is.GreaterThan(10));}
[Test] public void D07_TourOrientationChanges(){o.StartTour();var r=o.transform.rotation;o.AdvanceCamera(10);Assert.That(Quaternion.Angle(r,o.transform.rotation),Is.GreaterThan(10));}
[Test] public void D08_RouteHasSubstantialLength(){o.StartTour();float length=0;for(int i=1;i<o.TourWaypoints.Count;i++)length+=Vector3.Distance(o.TourWaypoints[i-1],o.TourWaypoints[i]);Assert.That(length,Is.GreaterThan(400));}
[Test] public void D09_RouteVisitsFourQuadrants(){o.StartTour();foreach(int x in new[]{-1,1})foreach(int z in new[]{-1,1})Assert.That(o.TourWaypoints.Any(p=>p.x*x>20&&p.z*z>20),Is.True);}
[Test] public void D10_RouteContainsIntersectionAndFrontages(){o.StartTour();Assert.That(o.TourWaypoints.Any(p=>Mathf.Abs(p.x)<1&&Mathf.Abs(p.z)<1&&p.y<3),Is.True);Assert.That(o.TourWaypoints.Any(p=>Mathf.Abs(p.x)>40&&p.y<3),Is.True);}
[Test] public void D11_GroundRouteSegmentsAvoidSolidBounds(){o.StartTour();for(int i=1;i<o.TourWaypoints.Count;i++){var a=o.TourWaypoints[i-1];var b=o.TourWaypoints[i];if(a.y>3||b.y>3)continue;for(int j=0;j<=100;j++)Assert.That(o.CanWalk(Vector3.Lerp(a,b,j/100f)),Is.True,$"segment {i} sample {j}");}}
[Test] public void D12_TourCompletesAtOverview(){o.StartTour();o.AdvanceCamera(500);Assert.That(o.TourRunning,Is.False);Assert.That(o.transform.position.y,Is.GreaterThan(20));}
[Test] public void D13_ControlsWorkAfterCompletion(){o.StartTour();o.AdvanceCamera(500);o.EnterExplorer(Vector3.zero);StepMove(Vector2.up);Assert.That(o.transform.position.z,Is.GreaterThan(0));}
[Test] public void D14_ResetInterruptsPausedTour(){o.StartTour();o.PauseTour();o.Home();Assert.That(o.TourRunning||o.TourPaused,Is.False);}
[Test] public void D15_RepeatedTourHasSingleController(){for(int i=0;i<50;i++){o.StartTour();o.AdvanceCamera(2);o.CancelTour();}Assert.That(app.GetComponentsInChildren<OrbitCamera>().Length,Is.EqualTo(1));Assert.That(o.TourRunning,Is.False);}
[Test] public void E01_DryStopsEmission(){Draw(0);Assert.That(P("Rainfall particles").emission.rateOverTime.constant,Is.Zero);}
[Test] public void E02_RainStartsEmission(){Draw();Assert.That(P("Rainfall particles").emission.rateOverTime.constant,Is.GreaterThan(0));}
[Test] public void E03_EmissionIncreasesWithRain(){Draw(10);float a=P("Rainfall particles").emission.rateOverTime.constant;Draw(150);Assert.That(P("Rainfall particles").emission.rateOverTime.constant,Is.GreaterThan(a));}
[Test] public void E04_RainUsesStretchedRendering(){Assert.That(P("Rainfall particles").GetComponent<ParticleSystemRenderer>().renderMode,Is.EqualTo(ParticleSystemRenderMode.Stretch));}
[Test] public void E05_RainCoversDistrictOverview(){var shape=P("Rainfall particles").shape;Assert.That(shape.scale.x,Is.GreaterThanOrEqualTo(100));Assert.That(shape.scale.z,Is.GreaterThanOrEqualTo(90));}
[Test] public void E06_RainVolumeIncludesStreetEntry(){o.EnterExplorer(new Vector3(0,2.2f,-34));Draw();var p=P("Rainfall particles");Assert.That(Mathf.Abs(o.transform.position.z-p.transform.position.z),Is.LessThan(p.shape.scale.z*.5f));Assert.That(p.emission.rateOverTime.constant,Is.GreaterThan(0));}
[Test] public void E07_WindChangesRainDrift(){Draw(40,0);float a=app.World.DisplayedWind.magnitude;Draw(40,180);Assert.That(app.World.DisplayedWind.magnitude,Is.GreaterThan(a));}
[Test] public void E08_InvalidDirectionDoesNotCreateNanMotion(){var w=W();w.WindDegrees=double.NaN;app.World.Render(new EnvironmentState{WindIntensity=1},w,5);Assert.That(float.IsNaN(app.World.DisplayedWind.x),Is.False);}
[Test] public void E09_WetRoadColorSurvivesCityView(){Draw(0,0,0,0);var road=app.World.transform.Find("East west avenue").GetComponent<Renderer>();var dry=road.sharedMaterial.color;Draw(40,40,30,1);app.Spatial.SetOverlay(DistrictOverlay.Normal);Assert.That(road.sharedMaterial.color.r,Is.LessThan(dry.r));var block=new MaterialPropertyBlock();road.GetPropertyBlock(block);Assert.That(block.isEmpty,Is.True);}
[Test] public void E10_StorageChangesBasinCoverage(){Draw(40,40,1);var b=app.World.transform.Find("Simulated detention storage");float a=b.localScale.x;Draw(40,40,100);Assert.That(b.localScale.x,Is.GreaterThan(a));}
[Test] public void E11_DrainageShrinksRenderedWater(){app.Engine.Step(W(),0,600);app.World.Render(app.Engine.State,W(),5);var b=app.World.transform.Find("Simulated detention storage");float before=b.localScale.x;app.Engine.Step(W(0),60,600);app.World.Render(app.Engine.State,W(0),5);Assert.That(b.localScale.x,Is.LessThan(before));}
[Test] public void E12_PuddlesTrackFullStorageRange(){Draw(40,40,40);var p=app.World.transform.Find("Puddle");float a=p.localScale.x;Draw(40,40,120);Assert.That(p.localScale.x,Is.GreaterThan(a));}
[Test] public void E13_RainActivatesImpacts(){Draw();Assert.That(P("Rain splash impacts").emission.rateOverTime.constant,Is.GreaterThan(0));}
[Test] public void E14_ImpactsStopWhenRainStops(){Draw();Draw(0);Assert.That(P("Rain splash impacts").emission.rateOverTime.constant,Is.Zero);Assert.That(P("Road rain ripples").emission.rateOverTime.constant,Is.Zero);}
[Test] public void E15_WindIncreasesTreeSway(){Draw(0,0);float a=Quaternion.Angle(app.World.Trees[0].localRotation,Quaternion.identity);Draw(0,180);Assert.That(Quaternion.Angle(app.World.Trees[0].localRotation,Quaternion.identity),Is.GreaterThan(a));}
[Test] public void E16_TreeSwayRemainsBounded(){Draw(40,180);foreach(var tree in app.World.Trees)Assert.That(Quaternion.Angle(tree.localRotation,Quaternion.identity),Is.LessThanOrEqualTo(7.01f));}
[Test] public void E17_EasterlyWindTravelsWest(){Draw(40,180);Assert.That(app.World.DisplayedWind.x,Is.LessThan(-8));Assert.That(Mathf.Abs(app.World.DisplayedWind.y),Is.LessThan(.01f));}
[Test] public void E18_CalmReturnsTreesToRest(){Draw(40,180);Draw(0,0);Assert.That(Quaternion.Angle(app.World.Trees[0].localRotation,Quaternion.identity),Is.LessThan(.01f));}
[Test] public void E19_CloudsDimTheLight(){Draw(0,0,0,0,0);float a=app.World.transform.Find("Daylight").GetComponent<Light>().intensity;Draw(0,0,0,0,100);Assert.That(app.World.transform.Find("Daylight").GetComponent<Light>().intensity,Is.LessThan(a));}
[Test] public void E20_SolarRadiationChangesSupportedLight(){Draw(0,0,0,0,30,800);float a=app.World.transform.Find("Daylight").GetComponent<Light>().intensity;Draw(0,0,0,0,30,0);Assert.That(app.World.transform.Find("Daylight").GetComponent<Light>().intensity,Is.LessThan(a));}
[Test] public void F01_DefaultVisualizationIsCity(){Assert.That(app.Spatial.Overlay,Is.EqualTo(DistrictOverlay.Normal));}
[Test] public void F02_CityViewButtonWorks(){app.Spatial.SetOverlay(DistrictOverlay.Water);Click("Spatial overlays/City View");Assert.That(app.Spatial.Overlay,Is.EqualTo(DistrictOverlay.Normal));}
[Test] public void F03_StandingWaterShowsActualVolume(){app.Engine.Step(W(),0,600);Click("Spatial overlays/Standing Water");Assert.That(app.Spatial.Legend,Does.Contain(app.Engine.State.CollectionM3.ToString("0.0")));}
[Test] public void F04_DrainageHighlightsRealChannels(){Click("Spatial overlays/Drainage");var r=app.World.transform.Find("Open stormwater channel").GetComponent<Renderer>();var b=new MaterialPropertyBlock();r.GetPropertyBlock(b);Assert.That(b.isEmpty,Is.False);Assert.That(app.Spatial.Legend,Does.Contain("mm/h nominal"));}
[Test] public void F05_WetnessViewShowsSharedState(){app.Engine.Step(W(),0,600);Click("Spatial overlays/Surface Wetness");Assert.That(app.Spatial.Legend,Does.Contain((app.Engine.State.Wetness*100).ToString("0")+"%"));}
[Test] public void F06_ComparisonCalculatesBothScenarios(){app.SetMode(WorldMode.WhatIf);app.Simulation.Scenario.RainMmPerHour=40;app.ApplyInputs();ui.OpenStudio();Assert.That(ui.Comparison,Is.Not.Null);Assert.That(ui.Comparison.Baseline.Seconds,Is.EqualTo(3600).Within(.01));}
[Test] public void F07_UnsupportedMenuLabelsAreAbsent(){foreach(string n in new[]{"Normal","Water","Runoff","Surfaces","Connections","Coverage"})Assert.That(Root.Find("Spatial overlays/"+n),Is.Null);}
[Test] public void F08_SelectionIsVisiblyIndicated(){Click("Spatial overlays/Standing Water");RefreshUi();var a=Root.Find("Spatial overlays/Standing Water").GetComponent<UnityEngine.UI.Image>().color;var b=Root.Find("Spatial overlays/City View").GetComponent<UnityEngine.UI.Image>().color;Assert.That(a,Is.Not.EqualTo(b));}
[Test] public void F09_CityViewClearsOverlayColor(){Click("Spatial overlays/Standing Water");Click("Spatial overlays/City View");var b=new MaterialPropertyBlock();app.World.transform.Find("East west avenue").GetComponent<Renderer>().GetPropertyBlock(b);Assert.That(b.isEmpty,Is.True);}
[Test] public void F10_FiveCityButtonsSelectCorrectLocation(){for(int i=0;i<5;i++){Click("Header/"+Location.All[i].Name);Assert.That(app.Weather.Selected,Is.EqualTo(i));app.Weather.CancelRequests();app.AirQuality.Cancel();Assert.That(app.Simulation.Live,Is.Null);}}
[Test] public void F11_ActualSliderPreservesLiveBaseline(){var live=W(3);app.Simulation.Live=live;app.SetMode(WorldMode.WhatIf);Root.Find("Scenario controls/What-if controls/RAINFALL/Track").GetComponent<UnityEngine.UI.Slider>().value=150;Assert.That(live.RainMmPerHour,Is.EqualTo(3));Assert.That(app.Simulation.Active.RainMmPerHour,Is.EqualTo(150));}
[Test] public void F12_ResetClearsScenarioStorage(){app.SetMode(WorldMode.WhatIf);app.Engine.Step(W(),0,600);Click("Scenario controls/What-if controls/Reset scenario");Assert.That(app.Engine.State.CollectionM3,Is.Zero);Assert.That(app.Simulation.Scenario.DrainageMmPerHour,Is.EqualTo(12));}
[Test] public void F13_HypotheticalDataHasModeLabel(){app.SetMode(WorldMode.WhatIf);RefreshUi();Assert.That(Root.Find("City heading/Simulation mode").GetComponent<TMP_Text>().text,Does.Contain("HYPOTHETICAL"));}
[Test] public void F14_DashboardMatchesStandingWaterState(){app.SetMode(WorldMode.WhatIf);app.Engine.Step(W(),0,600);RefreshUi();var text=Root.GetComponentsInChildren<TMP_Text>().First(x=>x.transform.parent.name=="SIMULATED STANDING WATER"&&x.name=="Value");Assert.That(text.text,Does.StartWith(app.Engine.State.CollectionM3.ToString("0.0")));}
[Test] public void F15_MissingInputsDisplayUnavailable(){app.SetMode(WorldMode.Live);RefreshUi();Assert.That(Root.Find("Weather data/TEMPERATURE/Value").GetComponent<TMP_Text>().text,Is.EqualTo("Unavailable"));}
[Test] public void G01_RepeatedRefreshCanBeCancelled(){for(int i=0;i<20;i++)app.Weather.Refresh();app.Weather.CancelRequests();Assert.That(app.Weather.Status.Loading,Is.False);}
[Test] public void G02_RapidCitySelectionKeepsLatest(){for(int i=0;i<30;i++)app.SelectLocation(i%5);app.Weather.CancelRequests();app.AirQuality.Cancel();Assert.That(app.Weather.Selected,Is.EqualTo(4));Assert.That(app.Weather.Current,Is.Null);}
[Test] public void G03_ModeSwitchDoesNotDuplicateEffects(){int count=app.GetComponentsInChildren<ParticleSystem>().Length;for(int i=0;i<30;i++)app.SetMode((WorldMode)(i%3));Assert.That(app.GetComponentsInChildren<ParticleSystem>().Length,Is.EqualTo(count));}
[Test] public void G04_TourRestartClearsPause(){for(int i=0;i<20;i++){o.StartTour();o.PauseTour();o.RestartTour();Assert.That(o.TourPaused,Is.False);}o.CancelTour();Assert.That(o.TourRunning,Is.False);}
[UnityTest] public IEnumerator G05_ReloadDisposesOldWorld(){var old=app.World;yield return SceneManager.LoadSceneAsync("Dhara");yield return null;Assert.That(old==null,Is.True);app=Object.FindFirstObjectByType<DharaApplication>();app.Weather.CancelRequests();app.AirQuality.Cancel();Assert.That(Object.FindObjectsByType<DharaApplication>(FindObjectsSortMode.None).Length,Is.EqualTo(1));}
[UnityTest] public IEnumerator G06_DestroyDisposesActiveRequest(){app.Weather.Refresh();Object.Destroy(app.gameObject);yield return null;Assert.That(app==null,Is.True);}
[Test] public void G07_RainParticleCountIsBounded(){for(int i=0;i<100;i++){Draw(i%2==0?200:0);P("Rainfall particles").Simulate(.1f,true,false);}Assert.That(P("Rainfall particles").particleCount,Is.LessThanOrEqualTo(P("Rainfall particles").main.maxParticles));}
[Test] public void G08_ImpactsReuseSameObjects(){int count=app.World.GetComponentsInChildren<Transform>().Length;for(int i=0;i<200;i++)Draw(i%2==0?200:0);Assert.That(app.World.GetComponentsInChildren<Transform>().Length,Is.EqualTo(count));}
[Test] public void G09_TreeRootsNeverDrift(){var positions=app.World.Trees.Select(x=>x.localPosition).ToArray();for(int i=0;i<100;i++)Draw(40,180);for(int i=0;i<positions.Length;i++)Assert.That(app.World.Trees[i].localPosition,Is.EqualTo(positions[i]));}
[Test] public void G10_RoadMaterialUpdatesDoNotChangeFacade(){var r=app.World.transform.Find("Building 1").GetComponent<Renderer>();var color=r.sharedMaterial.color;Draw(200,180,150,1);Assert.That(r.sharedMaterial.color,Is.EqualTo(color));}
