[Test] public void S32_HeavyRainCannotEnableObscuringBloom(){Draw(200,180,150,1);var volume=app.World.GetComponentInChildren<UnityEngine.Rendering.Volume>();UnityEngine.Rendering.Universal.Bloom bloom;Assert.That(volume.sharedProfile.TryGet(out bloom),Is.True);Assert.That(bloom.active,Is.True);Assert.That(bloom.intensity.overrideState,Is.True);Assert.That(bloom.intensity.value,Is.Zero);
var manager=UnityEngine.Rendering.VolumeManager.instance;bool owned=!manager.isInitialized;
UnityEngine.Rendering.VolumeProfile defaults=null;
if(owned){defaults=ScriptableObject.CreateInstance<UnityEngine.Rendering.VolumeProfile>();defaults.Add<UnityEngine.Rendering.Universal.Bloom>(true).intensity.Override(.25f);manager.Initialize(defaults);}
var stack=manager.CreateStack();
try{manager.Update(stack,app.World.ViewCamera.transform,1<<volume.gameObject.layer);var effective=stack.GetComponent<UnityEngine.Rendering.Universal.Bloom>();Assert.That(effective,Is.Not.Null);Assert.That(effective.intensity.value,Is.Zero);}finally{manager.DestroyStack(stack);if(owned){manager.Deinitialize();Object.Destroy(defaults);}}}
[Test] public void S33_StrongWindStillRainsAtCityEdge(){Draw(200,180,100,1);var rain=P("Rainfall particles");rain.Simulate(2.5f,true,true);var particles=new ParticleSystem.Particle[rain.main.maxParticles];int count=rain.GetParticles(particles);Assert.That(particles.Take(count).Any(p=>p.position.x>49&&p.position.y>0&&p.position.y<6&&Mathf.Abs(p.position.z)<20),Is.True,"Rain must reach the accessible upwind edge at street height");}
